SourceCode.Declaration:
/// <summary>
/// The controller class for the batch job
/// </summary>
class METAutoSettleCustomerTransactionsController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// The new method of the class
/// </summary>
protected void new(IdentifierName _className = classStr(METAutoSettleCustomerTransactionsService),
    IdentifierName _methodName = methodStr(METAutoSettleCustomerTransactionsService, process),
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription defaultCaption()
{
    return "@MET:AutoSettleCustTrans";
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    SysOperationController controller = new METAutoSettleCustomerTransactionsController();
    controller.startOperation();
}
